"""Creates the master player file ONCE from a V2 build (D-076). Refuses to run when a master exists (the master is never regenerated by script).
    blender -b <build .blend kept by tools/blender/v2/build_v2.py --keep-blend> --python tools/blender/master/create_master.py
It sorts the objects into the component collections, records provenance on the armature and saves art_source/players/fc_master_player.blend."""
import os
import sys

import bpy

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import master_lib as M  # noqa: E402


def main():
    if os.path.exists(M.MASTER):
        raise SystemExit("FC_MASTER exists already: %s (it is the source of truth and is never recreated by script)" % M.MASTER)
    scene = bpy.context.scene
    for cname in M.BODY_COLLECTIONS + M.PART_COLLECTIONS:
        if bpy.data.collections.get(cname) is None:
            scene.collection.children.link(bpy.data.collections.new(cname))
    moved = 0
    for obj in list(bpy.data.objects):
        cname = M.collection_for(obj.name)
        if cname == "":
            continue
        target = bpy.data.collections[cname]
        for c in list(obj.users_collection):
            c.objects.unlink(obj)
        target.objects.link(obj)
        moved += 1
    leftovers = [o.name for o in bpy.data.objects if not any(c.name.startswith("FC_") for c in o.users_collection)]
    for name in leftovers:
        bpy.data.objects.remove(bpy.data.objects[name], do_unlink=True)
    arm = bpy.data.objects["Armature"]
    arm["fc_master"] = "Full Court master player (D-076). Source of truth: edit by hand or modeling passes; export with tools/blender/master/export_master.py"
    arm["fc_master_origin"] = "MakeHuman CC0 base via MPFB 2.0.18 + Full Court V2.1 generator (tools/blender/v2), 2026-11-26"
    os.makedirs(M.MASTER_DIR, exist_ok=True)
    bpy.ops.wm.save_as_mainfile(filepath=M.MASTER, compress=True)
    print("FC_MASTER created: %d objects in %d collections, removed %s" % (moved, len(M.BODY_COLLECTIONS + M.PART_COLLECTIONS), leftovers))


main()
